


export type DeliveryFulfillmentDetailsInput = { "carrier"?: string; /** Time at which the courier collected the order. Format: date-time. */ "courier_pickup_at"?: string | globalThis.Date; /** Width of the promised courier pickup window, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "courier_pickup_window_duration_seconds"?: string; /** Delivery network or merchant fleet provider handling the job. maxLength: 255. */ "courier_provider_name"?: string; /** Buyer-safe support number for the courier or merchant fleet. maxLength: 30. */ "courier_support_phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "delivered_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "dispatched_at"?: string | globalThis.Date; /** Driver-facing notes for the final handoff. maxLength: 2048. */ "dropoff_notes"?: string; /** Deadline after which an undelivered job should enter merchant review. Format: date-time. */ "expires_at"?: string | globalThis.Date; /** Stable delivery job ID owned by the courier or merchant dispatch system. maxLength: 255. */ "external_delivery_id"?: string; "instructions"?: string; /** Whether the buyer requested a no-contact handoff. */ "no_contact"?: boolean; /** Expected preparation time before courier pickup, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "prep_time_duration_seconds"?: string; /** Time at which the order became ready for courier pickup. Format: date-time. */ "ready_at"?: string | globalThis.Date; "service_area_id"?: string; "timezone"?: string; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. */ "tracking_url"?: string; /** RFC3339 timestamp. Format: date-time. */ "window_end_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "window_start_at"?: string | globalThis.Date; };
